recipes.code:
{
  "inputs": [
    {
      "id": "filechanger-api-key",
      "type": "promptString",
      "description": "FileChanger API key (fc_...). Get one at https://filechanger.io.",
      "password": true
    }
  ],
  "servers": {
    "filechanger": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "filechanger-mcp@0.1.2"
      ],
      "env": {
        "FILECHANGER_API_KEY": "${input:filechanger-api-key}",
        "FILECHANGER_URL": "<filechanger-url>"
      }
    }
  }
}
